38	
39		/**
40		 * Simple formatting, for example '1s'.
41		 */
42		SIMPLE("^([+-]?\\d+)([a-zA-Z]{0,2})$") {
43	
44			@Override
45			public Duration parse(String value, @Nullable ChronoUnit unit) {
46				try {
47					Matcher matcher = matcher(value);
48					Assert.state(matcher.matches(), "Does not match simple duration pattern");
49					String suffix = matcher.group(2);
50					return (StringUtils.hasLength(suffix) ? Unit.fromSuffix(suffix) : Unit.fromChronoUnit(unit))
51						.parse(matcher.group(1));
52				}
53				catch (Exception ex) {
54					throw new IllegalArgumentException("'" + value + "' is not a valid simple duration", ex);
55				}
56			}
57	
58			@Override
59			public String print(Duration value, @Nullable ChronoUnit unit) {
60				return Unit.fromChronoUnit(unit).print(value);
61			}
62	
63		},
64	
65		/**
66		 * ISO-8601 formatting.
67		 */
68		ISO8601("^[+-]?[pP].*$") {
69	
70			@Override
71			public Duration parse(String value, @Nullable ChronoUnit unit) {
72				try {
73					return Duration.parse(value);
74				}
75				catch (Exception ex) {
76					throw new IllegalArgumentException("'" + value + "' is not a valid ISO-8601 duration", ex);
77				}
78			}
79	
80			@Override
81			public String print(Duration value, @Nullable ChronoUnit unit) {
82				return value.toString();
83			}
84	
85		};
