94			return this.pattern.matcher(value).matches();
95		}
96	
97		protected final Matcher matcher(String value) {
98			return this.pattern.matcher(value);
99		}
100	
101		/**
102		 * Parse the given value to a duration.
103		 * @param value the value to parse
104		 * @return a duration
105		 */
106		public Duration parse(String value) {
107			return parse(value, null);
108		}
