110		/**
111		 * Parse the given value to a duration.
112		 * @param value the value to parse
113		 * @param unit the duration unit to use if the value doesn't specify one ({@code null}
114		 * will default to ms)
115		 * @return a duration
116		 */
117		public abstract Duration parse(String value, @Nullable ChronoUnit unit);
118	
119		/**
120		 * Print the specified duration.
121		 * @param value the value to print
122		 * @return the printed result
123		 */
124		public String print(Duration value) {
125			return print(value, null);
126		}
127	
128		/**
129		 * Print the specified duration using the given unit.
130		 * @param value the value to print
131		 * @param unit the value to use for printing
132		 * @return the printed result
133		 */
134		public abstract String print(Duration value, @Nullable ChronoUnit unit);
135	
136		/**
137		 * Detect the style then parse the value to return a duration.
138		 * @param value the value to parse
139		 * @return the parsed duration
140		 * @throws IllegalArgumentException if the value is not a known style or cannot be
141		 * parsed
142		 */
143		public static Duration detectAndParse(String value) {
144			return detectAndParse(value, null);
145		}
