147		/**
148		 * Detect the style then parse the value to return a duration.
149		 * @param value the value to parse
150		 * @param unit the duration unit to use if the value doesn't specify one ({@code null}
151		 * will default to ms)
152		 * @return the parsed duration
153		 * @throws IllegalArgumentException if the value is not a known style or cannot be
154		 * parsed
155		 */
156		public static Duration detectAndParse(String value, @Nullable ChronoUnit unit) {
157			return detect(value).parse(value, unit);
158		}
