161		 * Detect the style from the given source value.
162		 * @param value the source value
163		 * @return the duration style
164		 * @throws IllegalArgumentException if the value is not a known style
165		 */
166		public static DurationStyle detect(String value) {
167			Assert.notNull(value, "'value' must not be null");
168			for (DurationStyle candidate : values()) {
169				if (candidate.matches(value)) {
170					return candidate;
171				}
172			}
173			throw new IllegalArgumentException("'" + value + "' is not a valid duration");
174		}
