176		/**
177		 * Units that we support.
178		 */
179		enum Unit {
180	
181			/**
182			 * Nanoseconds.
183			 */
184			NANOS(ChronoUnit.NANOS, "ns", Duration::toNanos),
185	
186			/**
187			 * Microseconds.
188			 */
189			MICROS(ChronoUnit.MICROS, "us", (duration) -> duration.toNanos() / 1000L),
190	
191			/**
192			 * Milliseconds.
193			 */
194			MILLIS(ChronoUnit.MILLIS, "ms", Duration::toMillis),
195	
